from collections import Counter
from lib import stamp_shape_on_fitting_spots

def transform(grid):
    color = Counter(v for row in grid for v in row).most_common()[-1][0]
    return stamp_shape_on_fitting_spots(grid, color, bg=0)

"""Shared library of reusable grid transforms for ARC-style tasks."""

def find_background(grid):
    """Return the most common cell value (the background color)."""
    from collections import Counter
    return Counter(v for row in grid for v in row).most_common(1)[0][0]


def find_objects(grid, bg=None):
    """Split non-background cells into (multi_cell_objects, isolated_single_cells).

    Objects are 4-connected groups with >= 2 cells; singles are isolated cells.
    Each object is returned as a dict of {(r, c): color}.
    """
    from collections import Counter, deque
    h, w = len(grid), len(grid[0])
    if bg is None:
        bg = find_background(grid)
    cells = {(i, j) for i in range(h) for j in range(w) if grid[i][j] != bg}
    seen, groups = set(), []
    for cell in cells:
        if cell in seen:
            continue
        q, comp = deque([cell]), []
        seen.add(cell)
        while q:
            r, c = q.popleft()
            comp.append((r, c))
            for dr, dc in ((1,0),(-1,0),(0,1),(0,-1)):
                n = (r+dr, c+dc)
                if n in cells and n not in seen:
                    seen.add(n)
                    q.append(n)
        groups.append(comp)
    objs = [{(r, c): grid[r][c] for r, c in comp} for comp in groups if len(comp) > 1]
    singles = [comp[0] for comp in groups if len(comp) == 1]
    return objs, singles


def stamp_objects_at_points(grid, obj, positions, anchor):
    """Return a copy of grid with obj stamped so its `anchor` cell lands on
    every (r, c) in `positions`; out-of-bounds parts are clipped."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    ar, ac = anchor
    for (r, c) in positions:
        for (i, j), v in obj.items():
            ii, jj = r + (i - ar), c + (j - ac)
            if 0 <= ii < h and 0 <= jj < w:
                out[ii][jj] = v
    return out


def stamp_shape_on_fitting_spots(grid, color, bg=0):
    """Stamp the shape made of `color` cells (relative to its top-left) at every
    offset where all of the shape's cells would land on `bg` cells."""
    h, w = len(grid), len(grid[0])
    cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == color]
    r0 = min(r for r, c in cells); c0 = min(c for r, c in cells)
    mask = [(r - r0, c - c0) for r, c in cells]
    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if all(0 <= r + dr < h and 0 <= c + dc < w and grid[r + dr][c + dc] == bg
                   for dr, dc in mask):
                for dr, dc in mask:
                    out[r + dr][c + dc] = color
    return out

